// Normalisation défensive du payload Sembly (schéma non documenté publiquement :
// on extrait au mieux et on conserve TOUT le brut pour ajuster le mapping ensuite).
const b = $json.body ?? $json

const premier = (...vals) => vals.find((v) => v !== undefined && v !== null && v !== '')

const titre = premier(
  b.meeting_title, b.meetingTitle, b.title, b.meeting?.title, b.meeting?.name, b.name,
) ?? 'Call sans titre'

const dateIso = (() => {
  const d = premier(b.meeting_date, b.meetingDate, b.date, b.started_at, b.start_time, b.meeting?.date, b.meeting?.started_at)
  const parsed = d ? new Date(d) : new Date()
  return isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString()
})()

const partBruts = premier(b.participants, b.attendees, b.meeting?.participants, b.meeting?.attendees) ?? []
const participants = (Array.isArray(partBruts) ? partBruts : [])
  .map((p) => (typeof p === 'string' ? p : premier(p?.name, p?.full_name, p?.fullName, p?.email)))
  .filter(Boolean)

const enTexte = (v) => (v == null ? null : typeof v === 'string' ? v : JSON.stringify(v, null, 2))

const transcript = enTexte(premier(b.transcription, b.transcript, b.transcript_text))
const notes = enTexte(premier(b.notes, b.meeting_notes, b.meetingNotes, b.minutes, b.summary))

// Tâche individuelle (Sembly pousse une requête par tâche)
const estTache = !transcript && !notes && premier(b.task_title, b.taskTitle, (b.title && (b.due_date || b.dueDate || b.description)) ? b.title : undefined)
let type = 'inconnu'
let contenu = null
if (transcript) { type = 'transcription'; contenu = transcript }
else if (notes) { type = 'notes'; contenu = notes }
else if (estTache) {
  type = 'task'
  const due = premier(b.due_date, b.dueDate)
  const desc = premier(b.description, b.task_description)
  contenu = `- [ ] ${estTache}${due ? ` (échéance ${due})` : ''}${desc ? `\n  ${desc}` : ''}`
} else {
  contenu = enTexte(b)
}

const slug = String(titre).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase().slice(0, 60)
const cle = `${dateIso.slice(0, 10)}-${slug}`

return [{ json: { cle, type, titre, date_iso: dateIso, participants, contenu, brut: JSON.stringify(b) } }]
